const $=s=>document.querySelector(s);
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2zM12 6v15"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',chart:'<path d="M4 3v18h17M9 16v-5m5 5V6m5 10V9"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m3-10a3 3 0 1 0-1-6m4 16v-3a6 6 0 0 0-3-5"/>',music:'<path d="M9 18V5l11-2v13M9 9l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',leaf:'<path d="M5 21c0-9 6-12 12-16M5 16C-1 5 10 1 21 3c0 10-6 17-16 13"/>',bell:'<path d="M5 9a7 7 0 0 1 14 0v6l2 3H3l2-3zM9 21h6"/>',play:'<path d="m8 4 12 8-12 8z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L20 5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.music}</svg>`;
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('shanyin-demo')||'null')}catch{}
let state={route:'home',tab:'plan',grade:'四年级',students:28,duration:40,song:'茉莉花',level:'初学者',equipment:'无钢琴',request:'',plan:null,stage:0,analysis:null,attempt:0,records:[],...saved};
state.route=location.hash.slice(1)||'home';let busy=false,recording=false,recorder,stream,recordedURL,timer,seconds=0,audioContext,audioNodes=[],playTimer,voiceRecognition;
const persist=()=>{try{localStorage.setItem('shanyin-demo',JSON.stringify({...state,route:'home'}))}catch{}};
const toast=t=>{const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),3300)};
const button=(t,action,kind='',ic='')=>`<button class="btn ${kind}" data-action="${action}">${ic?icon(ic):''}${t}</button>`;
function header(){return `<header><a class="brand" href="#home"><span class="brand-mark">🏞️</span><div><b>山音AI课</b><small>SHANYIN · AI MUSIC CLASS</small></div></a><span class="brand-line">AI，让音乐课在山里发生</span><nav aria-label="主导航">${[['home','首页','home'],['classroom','今日课堂','book'],['listen','AI听唱','mic'],['reports','课堂报告','chart'],['classes','我的班级','users'],['sounds','山野声音','music']].map(([r,t,i])=>`<button class="${state.route===r?'active':''}" data-route="${r}">${icon(i)}${t}</button>`).join('')}</nav><div class="account"><button class="bell" data-action="notifications" aria-label="通知">${icon('bell')}</button><span class="avatar">🧑🏻‍🏫</span><span>徐老师</span></div></header>`}
function footer(){return `<footer><span>🌱　山音 AI 课　 |　 让每一座大山，都听见音乐课</span><span>音乐，连接更大的世界 ♫</span></footer>`}
function home(){return `<section class="home-hero"><span class="home-demo-note">山音教室 · 交互演示版</span><h1 class="hero-title">你好，徐老师。</h1><p class="hero-subtitle">今天，想带孩子们听见什么？</p><aside class="season"><div class="season-top"><b>山音教室</b><span class="sun">☀</span></div><p>${new Date().getMonth()+1}月${new Date().getDate()}日 · ${['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][new Date().getDay()]}</p><hr><em>每一个声音<br>都值得被听见 ♧</em></aside><div class="composer"><div class="compose-heading"><div class="guide-avatar">🧑🏻‍🌾</div><div><h2>和山音说说今天的课</h2><p>告诉我年级、人数、课堂时间和想教的内容，剩下的交给我。</p></div></div><div class="text-wrap"><textarea id="request" maxlength="200" aria-label="今天的课堂需求" placeholder="例如：帮四年级28个孩子准备一节40分钟的《茉莉花》音乐课，&#10;他们是初学者，没有钢琴。">${esc(state.request)}</textarea><span class="counter">${state.request.length}/200</span></div><div class="chips"><button class="chip" data-action="conditions">${state.grade}</button><button class="chip" data-action="conditions">${state.duration}分钟</button><button class="chip" data-action="conditions">${state.level}</button><button class="chip" data-action="conditions">${state.equipment}</button><button class="chip" data-action="conditions">《${esc(state.song)}》</button><button class="chip outline" data-action="conditions">＋ 更多条件</button></div><div class="compose-actions">${button('语音输入','voice','secondary','mic')}${button('开始 AI 备课','prepare','primary','spark')}</div><p class="compose-note">山音会结合学生水平、教学条件和音乐知识规划课堂。</p></div><div class="scene-caption">听见山野，也听见未来 ♫</div></section><section class="home-bottom"><div><div class="section-heading"><h2>${icon('leaf')}快速开始</h2></div><div class="quick-grid">${[['📖','继续上一节课',`${state.grade} · 《${esc(state.song)}》`,'继续课堂','continue'],['📝','快速创建课堂','沿用上一次班级设置','开始备课','prepare'],['🏞️','从乡音开始','用身边的声音上一节音乐课','探索山音','sounds']].map(([i,t,d,b,a])=>`<article class="quick-card"><div class="quick-top"><span class="quick-icon">${i}</span><div><h3>${t}</h3><p>${d}</p></div></div>${button(b,a,'secondary','arrow')}</article>`).join('')}</div></div><div class="recent-section"><div class="section-heading"><h2>${icon('clock')}最近课堂</h2><button class="text-btn" data-route="reports">查看全部 ${icon('arrow')}</button></div><div class="recent-grid">${recentCard('茉莉花','四年级',28,'9月10日',86,89,'🌼')}${recentCard('小雨沙沙','三年级',23,'9月8日',78,82,'🌧️')}</div></div></section>`}
function recentCard(song,grade,n,date,p,r,emoji){return `<article class="recent-card"><div class="recent-top"><div class="song-cover ${emoji==='🌧️'?'rain':''}">${emoji}</div><div><h3>《${song}》</h3><p>${grade} · ${n}人</p><p>${date} <span class="muted">· 示例</span></p></div></div><div class="mini-bar">音准掌握<div class="bar"><i style="width:${p}%"></i></div>${p}%</div><div class="mini-bar">节奏掌握<div class="bar blue"><i style="width:${r}%"></i></div>${r}%</div><button class="text-btn" data-action="sample-report" data-song="${song}">查看报告 ${icon('arrow')}</button></article>`}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p></div>${action}</div>`}
function agentPanel(done=4){const steps=[['理解课堂条件',`${state.grade} · ${state.students}人 · ${state.duration}分钟`],['匹配教学内容',`使用内置《${esc(state.song)}》教学模板`],['选择教学策略',state.equipment==='无钢琴'?'用电子音示范与身体律动替代钢琴。':'结合键盘示范和分句跟唱。'],['安排课堂时间','热身 → 聆听 → 跟唱 → 反馈'],['观察与调整','根据练习结果，选择下一步训练。']];return `<aside class="agent-panel"><h3>🌱 山音的课堂助手 <span class="badge">演示</span></h3>${steps.map(([t,d],i)=>`<div class="agent-step ${i>=done?'pending':''}">${t}${i<done?`<p>${d}</p>`:''}</div>`).join('')}<div class="agent-note">本版通过内置规则和教学模板演示规划过程，尚未接入大模型。任务状态展示可观察的操作与结果。</div></aside>`}
function notation(){return (state.song==='两只老虎'?['1','2','3','1','1','2']:state.song==='小雨沙沙'?['3','3','2','1','2','2']:['3','3','5','6','1̇','6']).map(n=>`<span>${n}</span>`).join('')}
const titles=['听见山野 · 声音热身','找到节拍 · 身体律动','听一听 · 旋律示范','唱一句 · 分句跟唱','试一试 · AI听唱','再进步 · 针对性练习','留住今天 · 课堂总结'];
const descriptions=['从身边的自然声音开始，轻声模仿鸟鸣。','用拍手与轻拍膝盖，感受强弱节拍。','先听完整乐句，再用手势画出旋律。','放慢速度，一句一句把旋律唱熟。','使用示例演唱，观察音准与节奏反馈。','根据反馈选择阶梯音或慢速跟拍练习。','说说今天的收获，保存课堂报告。'];
function makePlan(){const ratios=[5,7,5,10,6,5,2],minutes=ratios.map(n=>Math.max(1,Math.floor(n/40*state.duration)));let remaining=state.duration-minutes.reduce((a,b)=>a+b,0);for(let i=0;remaining>0;i++,remaining--)minutes[i%7]++;state.plan=ratios.map((n,i)=>({title:titles[i],desc:descriptions[i],min:minutes[i]}));const localSound=['林间鸟鸣','屋檐下的雨','竹林里的风'].find(s=>state.request.includes(s));if(localSound)state.plan[0].desc=`从${localSound}开始，先聆听，再用人声或身体动作模仿。`;if(state.request.includes('复习阶梯音')){state.plan[0].title='温故知新 · 阶梯音复习';state.plan[0].desc='先听Mi—Sol，轻声模唱两音上行，再回到主题乐句。';}state.stage=0;state.analysis=null;state.attempt=0;persist()}
function timeline(){return state.plan.map((s,i)=>`<div class="timeline-item ${i===state.stage?'current':''}"><div class="step-number">${String(i+1).padStart(2,'0')}</div><div class="timeline-text"><h3>${s.title}</h3><p>${s.desc}</p></div><span class="duration">${s.min} 分钟</span></div>`).join('')}
function classroom(){if(!state.plan)return `<main class="page">${heading('TODAY’S CLASS','今天，从一节音乐课开始','给山音一点课堂信息，一起把音乐带进教室。')}<div class="panel empty"><div class="big-icon">📖</div><h2>还没有准备今天的课堂</h2><p>选择班级、歌曲和课堂时长，即可生成可执行的课堂时间轴。</p>${button('准备我的第一节课','home','','spark')}</div></main>`;return `<main class="page">${heading('TODAY’S CLASS',`《${esc(state.song)}》的山间音乐课`,`${state.grade} · ${state.students}位孩子 · ${state.duration}分钟 · ${state.level}`,`<span class="status-pill">${state.tab==='teach'?'课堂进行中':'教案已准备好'}</span>`)}<div class="tabs"><button class="${state.tab==='plan'?'active':''}" data-tab="plan">01　AI备课</button><button class="${state.tab==='timeline'?'active':''}" data-tab="timeline">02　课堂时间轴</button><button class="${state.tab==='teach'?'active':''}" data-tab="teach">03　开始上课</button></div><div class="layout"><section class="panel">${state.tab==='teach'?teach():state.tab==='timeline'?`<h2>${state.duration}分钟，循序渐进地学会一首歌</h2><div class="timeline">${timeline()}</div><div class="panel-actions">${button('开始上课','start-class','','play')}</div>`:`<h2>这节课，为你的班级量身安排</h2><div class="summary-box">${state.level==='初学者'?'孩子们刚刚开始接触音乐，以模仿和游戏为主。':'孩子们已有音乐基础，增加旋律听辨和独立演唱。'}${state.equipment==='无钢琴'?'没有钢琴也没关系：用电子音示范、拍手和轻声哼唱完成课堂。':'用键盘示范辅助音高练习，再过渡到独立演唱。'}</div><div class="condition-grid">${[['年级',state.grade],['班级人数',state.students+'人'],['课堂时长',state.duration+'分钟'],['音乐基础',state.level],['教学条件',state.equipment],['本课歌曲','《'+esc(state.song)+'》']].map(([a,b])=>`<div class="field"><label>${a}</label><div>${b}</div></div>`).join('')}</div><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>本节课的小目标</h3><p>① 用身体感受稳定的节拍<br>② 聆听并模唱歌曲的主题乐句<br>③ 根据反馈，完成一次有针对性的再练习</p><div class="panel-actions">${button('调整条件','conditions','secondary')}${button('查看课堂时间轴','timeline','','arrow')}</div>`}</section>${agentPanel(state.analysis?5:4)}</div></main>`}
function teach(){const s=state.plan[state.stage];return `<div class="section-heading"><span class="badge">环节 ${state.stage+1} / 7</span><span class="duration">建议 ${s.min} 分钟</span></div><div class="progress-track"><div style="width:${(state.stage+1)/7*100}%"></div></div><div class="lesson-stage"><span class="big-icon">${['🌿','👏','🎵','🎶','🎤','🌱','🌼'][state.stage]}</span><h2>${s.title.split(' · ')[1]}</h2><p>${s.desc}</p><div class="notes">${notation()}</div><div class="toolbar">${button(state.stage===1?'播放节拍':'播放旋律示范',state.stage===1?'metronome':'melody','light','play')}${button('朗读课堂指引','speak','secondary')}</div><div class="lesson-tips"><b>给老师的小提示</b><br>${['请孩子闭上眼睛，听一听教室窗外的声音。用“呜”和“啾”做轻柔的声音模仿，不喊叫。','邀请孩子站起来：第一拍拍手，第二拍轻拍膝盖。先保持稳定，再加入旋律。','这里播放的是电子音旋律示范。请孩子先听，不急着唱，用手势跟随音高。','用“啦”轻声模唱，一次只练两到三个音。唱不准时先降低速度。','演示模式提供可重复的示例结果。真实录音可回听，本版不对录音自动评分。','先解决一个问题，再回到完整乐句。鼓励孩子描述自己听到的变化。','报告保留本次演示结果和下一节课建议，可下载为文本。'][state.stage]}</div></div><div class="panel-actions">${state.stage>0?button('上一环节','prev-stage','secondary'):''}${state.stage===4||state.stage===5?button('进入AI听唱','listen','','mic'):state.stage===6?button('生成课堂报告','finish','','check'):button('下一环节','next-stage','','arrow')}</div>`}
function listen(){return `<main class="page">${heading('LISTEN · PRACTICE · GROW','每一次开口，都离音乐更近一点',`《${esc(state.song)}》· 主题乐句练习`,state.analysis?button('保存课堂报告','finish','secondary','arrow'):'')}<div class="layout"><section class="panel"><div class="section-heading"><h2>听一听，再轻轻唱出来</h2><span class="badge">电子音示范</span></div><div class="notes">${notation()}</div><div class="toolbar">${button('听旋律示范','melody','light','play')}${button('慢速练习','slow-melody','secondary')}</div>${state.analysis?analysisView():`<div class="recorder ${recording?'recording':''}"><div class="mic-circle">${icon('mic')}</div><h3>${recording?'正在记录你的歌声…':'准备好了，就唱给山音听'}</h3><p>${recording?'<span id="record-time">00:00</span> · 最长60秒':'可以录下自己的歌声回听，或使用示例体验完整反馈。'}</p><div class="wave">${Array.from({length:30},(_,i)=>`<i style="height:${8+Math.sin(i*1.8)**2*35}px"></i>`).join('')}</div><div class="toolbar">${button(recording?'结束录音':'开始录音',recording?'stop-record':'record',recording?'secondary':'','mic')}${button('使用示例演唱','sample','secondary')}</div><div id="recording-result">${recordedURL?`<audio class="result-audio" controls src="${recordedURL}"></audio><p class="fine-print">录音仅保留在当前浏览器会话中，可回听；尚未接入自动音准检测。</p>`:''}</div></div><p class="fine-print">演示说明：示例演唱使用预设音准与节奏数据。真实录音不会被上传，也不会生成模拟评分。</p>`}</section><aside class="agent-panel"><h3>🌱 让练习有方向</h3><div class="agent-step">先聆听<p>播放标准音高，熟悉乐句。</p></div><div class="agent-step ${state.analysis?'':'pending'}">发现问题<p>${state.analysis?'示例结果：'+state.analysis.issue:'使用示例后，展示问题定位。'}</p></div><div class="agent-step ${state.analysis?'':'pending'}">选择练习<p>${state.analysis?state.analysis.strategy:'根据音准和节奏，选择适合的训练。'}</p></div><div class="agent-step ${state.attempt>1?'':'pending'}">再次尝试<p>对比两次示例表现，记录进步。</p></div><div class="agent-note">这是可操作的教学反馈流程原型。真实演唱评估与模型推理需在后续版本接入。</div></aside></div></main>`}
function analysisView(){const a=state.analysis;return `<div class="summary-box"><b>${state.attempt>1?'🌼 这一次，唱得更稳了':'🌱 找到一个可以进步的小地方'}</b><br>${a.issue} <span class="badge">示例数据 · 第${state.attempt}次</span></div><div class="scores"><div class="score"><strong>${a.pitch}<small style="font-size:16px">%</small></strong><span>示例音准匹配</span></div><div class="score"><strong>${a.rhythm}<small style="font-size:16px">%</small></strong><span>示例节奏匹配</span></div></div><div class="decision"><b>山音选择：${a.strategy}</b><br>${a.reason}</div><div class="toolbar">${state.attempt===1?button('开始针对性训练','training','','play'):button('再听一次练习','training','light','play')}${button(state.attempt===1?'练习后再次检测（示例）':'重新体验示例','retest','secondary')}</div><button class="text-btn" data-action="reset-analysis">返回录音 ${icon('arrow')}</button>`}
function reports(){return `<main class="page">${heading('CLASSROOM JOURNAL','把每一点进步，留在这里','记录课堂中的发现，也为下一次相遇做好准备。')}<div class="report-list">${state.records.map((r,i)=>`<article class="panel report-row"><div><h3>🌼 《${esc(r.song)}》课堂报告</h3><p>${r.grade} · ${r.students}人 · ${r.date} <span class="badge">演示记录</span></p></div><button class="btn secondary small" data-report="${i}">查看报告 ${icon('arrow')}</button></article>`).join('')}<article class="panel report-row"><div><h3>🌼 《茉莉花》课堂报告</h3><p>四年级 · 28人 · 9月10日 <span class="badge">示例报告</span></p></div><button class="btn secondary small" data-action="sample-report" data-song="茉莉花">查看报告 ${icon('arrow')}</button></article><article class="panel report-row"><div><h3>🌧️ 《小雨沙沙》课堂报告</h3><p>三年级 · 23人 · 9月8日 <span class="badge">示例报告</span></p></div><button class="btn secondary small" data-action="sample-report" data-song="小雨沙沙">查看报告 ${icon('arrow')}</button></article></div></main>`}
let selectedReport=null;
function report(){const r=selectedReport||state.records[0];if(!r)return reports();return `<main class="page">${heading('A LITTLE PROGRESS, EVERY DAY',`《${esc(r.song)}》课堂报告`,`${r.grade} · ${r.students}人 · ${r.date} · 示例数据，仅用于演示`,button('下载报告','download','secondary','download'))}<div class="report-grid"><div class="stat"><label>课堂时长</label><strong>${r.duration}<small> 分钟</small></strong><small>计划课堂时长</small></div><div class="stat"><label>示例音准匹配</label><strong>${r.pitch}%</strong><small>${r.attempt>1?'较首次示例提升 '+(r.pitch-64)+' 个百分点':'首次练习示例'}</small></div><div class="stat"><label>示例节奏匹配</label><strong>${r.rhythm}%</strong><small>${r.attempt>1?'较首次示例提升 '+(r.rhythm-81)+' 个百分点':'首次练习示例'}</small></div></div><div class="layout"><section class="panel"><h2>练习前后，看得见的变化</h2><p>浅绿：首次示例　深绿：${r.attempt>1?'再次练习示例':'当前示例（尚未复测）'}</p><div class="report-chart">${[['音准',64,r.pitch],['节奏',81,r.rhythm]].map(([t,a,b])=>`<div class="chart-group"><div class="chart-column" style="height:${a}%"><b>${a}%</b></div><div class="chart-column after" style="height:${b}%"><b>${b}%</b></div><label>${t}</label></div>`).join('')}</div><hr style="border:0;border-top:1px solid var(--line);margin:27px 0"><h3>这节课，我们发现</h3><p>${r.attempt>1?'在预设演示中，阶梯音练习后音准匹配提高。真实课堂效果仍需通过实际试教与音频评估验证。':'示例乐句的上行音偏低，适合先做两音模唱，再回到完整乐句。'}</p><div class="summary-box"><b>下一节课的小建议</b><br>用3分钟复习阶梯音；先唱“Mi—Sol”，再练主题乐句。保持轻声、自然的演唱，不急着提高音量。</div><div class="panel-actions">${button('返回课堂报告','reports','secondary')}${button('按建议准备下一节课','next-lesson','','arrow')}</div></section><aside class="agent-panel"><h3>🌱 课堂里的小收获</h3><div class="agent-step">聆听<p>从自然声音走近音乐。</p></div><div class="agent-step">尝试<p>通过模唱认识旋律的高低。</p></div><div class="agent-step">调整<p>使用阶梯音练习改善示例问题。</p></div><div class="agent-note">此报告展示课堂反馈结构，不代表真实学生或班级测评结果。</div></aside></div></main>`}
function classes(){return `<main class="page">${heading('OUR LITTLE CLASSROOMS','我的班级','熟悉每一个班，让每一节音乐课更合适。',button('添加班级','add-class','secondary','users'))}<div class="class-grid">${(state.classes||[{name:'四年级',students:28,level:'初学者',emoji:'🌻'},{name:'三年级',students:23,level:'初学者',emoji:'🌱'},{name:'五年级',students:26,level:'有一定基础',emoji:'🌳'}]).map((c,i)=>`<article class="class-card"><div class="class-avatar">${c.emoji||'🌻'}</div><h2>${esc(c.name)}</h2><p>${c.students}位孩子 · ${esc(c.level)}</p><div class="summary-box">让每个孩子，都有开口唱歌的机会。</div><button class="btn secondary" data-class="${i}">为这个班备课 ${icon('arrow')}</button></article>`).join('')}</div><p class="fine-print">初始班级为示例。新增班级仅保存在当前浏览器，请勿填写学生个人敏感信息。</p></main>`}
function sounds(){return `<main class="page">${heading('MUSIC IS ALL AROUND','山野，就是我们的音乐教室','从熟悉的乡音出发，发现节奏、音高和音色。')}<div class="sound-grid">${[['🐦','林间鸟鸣','短短长，听见鸟鸣里的节奏。试着用轻轻的“啾”模仿高低音。','birds','音高与模仿'],['🌧️','屋檐下的雨','滴答、滴答。用手指轻敲桌面，把雨点变成稳定的节拍。','rain','节奏与强弱'],['🎋','竹林里的风','沙沙作响的叶片，也有自己的音色。用纸张摩擦模拟风声。','wind','音色与聆听']].map(([em,t,d,a,tag])=>`<article class="panel sound-card"><div class="sound-art">${em}</div><h2>${t}</h2><span class="badge">${tag}</span><p>${d}</p><div class="toolbar">${button('听声音',a,'light','play')}<button class="btn secondary small" data-soundlesson="${t}">带进课堂</button></div></article>`).join('')}</div><p class="fine-print">本版声音为浏览器合成的教学音效，用于模仿活动，不是野外实录或物种识别。</p></main>`}
function render(){const route=state.route;$('#app').innerHTML=header()+({home,classroom,listen,reports,report,classes,sounds}[route]||home)()+footer();document.title=(route==='home'?'山音AI课':'山音AI课 · '+({classroom:'今日课堂',listen:'AI听唱',reports:'课堂报告',report:'课堂报告',classes:'我的班级',sounds:'山野声音'}[route]||''));}
function stopSound(){audioNodes.forEach(n=>{try{n.stop()}catch{}});audioNodes=[];clearTimeout(playTimer);document.querySelectorAll('.playing').forEach(n=>n.classList.remove('playing'))}
function go(route){stopSound();if(recording)stopRecording();state.route=route;if(location.hash!==`#${route}`)location.hash=route;render();window.scrollTo({top:0,behavior:'smooth'})}
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1)||'home';if(state.route!==r)go(r)});
function parseRequest(){const t=state.request;const grade=t.match(/([一二三四五六])年级/);const n=t.match(/(\d+)\s*(?:个孩子|位孩子|名学生|人|个学生)/);const dur=t.match(/(\d+)\s*分钟/);const song=t.match(/《([^》]+)》/);if(grade)state.grade=grade[0];if(n)state.students=Math.min(80,Math.max(1,+n[1]));if(dur)state.duration=Math.min(90,Math.max(10,+dur[1]));if(song&&['茉莉花','小雨沙沙','两只老虎'].includes(song[1]))state.song=song[1];if(/没有钢琴|无钢琴/.test(t))state.equipment='无钢琴';else if(/有钢琴/.test(t))state.equipment='有钢琴';if(/初学|没学过|零基础/.test(t))state.level='初学者';else if(/有基础|有一定基础/.test(t))state.level='有一定基础';}
async function prepare(){if(busy)return;state.request=$('#request')?.value??state.request;parseRequest();const supplied=state.request.match(/《([^》]+)》/);if(supplied&&!['茉莉花','小雨沙沙','两只老虎'].includes(supplied[1])){toast('演示版支持《茉莉花》《小雨沙沙》《两只老虎》，请在更多条件中选择。');return}busy=true;makePlan();state.analysis=null;state.attempt=0;state.tab='plan';go('classroom');const panel=$('.layout .panel');panel.innerHTML='<h2>山音正在准备这节课…</h2><p>把课堂需求，变成一步步能执行的教学安排。</p><div class="progress-track"><div id="plan-progress" style="width:0"></div></div><div id="plan-log"></div>';const messages=[`已识别：${state.grade}、${state.students}人、${state.duration}分钟。`,`已选择《${state.song}》内置教学模板。`,state.equipment==='无钢琴'?'无钢琴：选择电子音示范与身体律动。':'有钢琴：加入键盘音高辅助。',`已分配7个教学环节，共${state.duration}分钟。`];for(let i=0;i<messages.length;i++){await new Promise(r=>setTimeout(r,480));if($('#plan-log')){$('#plan-log').insertAdjacentHTML('beforeend',`<div class="agent-step">${esc(messages[i])}</div>`);$('#plan-progress').style.width=(i+1)*25+'%'}}busy=false;persist();if(state.route==='classroom')render();toast('教案准备好了，来看看今天的课堂。')}
function modal(html){document.body.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="关闭">×</button>${html}</section></div>`);$('.modal input,.modal select,.modal button')?.focus()}
function closeModal(){$('.modal-overlay')?.remove()}
function conditions(){state.request=$('#request')?.value??state.request;modal(`<h2>今天的课堂条件</h2><form id="condition-form"><div class="condition-grid"><div class="field"><label for="grade">年级</label><select id="grade" name="grade">${['一年级','二年级','三年级','四年级','五年级','六年级'].map(v=>`<option ${v===state.grade?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="students">班级人数</label><input id="students" name="students" type="number" min="1" max="80" required value="${state.students}"></div><div class="field"><label for="duration">课堂时长（分钟）</label><input id="duration" name="duration" type="number" min="10" max="90" required value="${state.duration}"></div><div class="field"><label for="level">音乐基础</label><select id="level" name="level"><option ${state.level==='初学者'?'selected':''}>初学者</option><option ${state.level!=='初学者'?'selected':''}>有一定基础</option></select></div><div class="field"><label for="equipment">教学条件</label><select id="equipment" name="equipment"><option ${state.equipment==='无钢琴'?'selected':''}>无钢琴</option><option ${state.equipment==='有钢琴'?'selected':''}>有钢琴</option></select></div><div class="field"><label for="song">本课歌曲</label><select id="song" name="song">${['茉莉花','小雨沙沙','两只老虎'].map(v=>`<option ${state.song===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="panel-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button class="btn" type="submit">保存条件</button></div></form>`)}
function getAudio(){audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();return audioContext}
function tone(freq,start,duration,type='sine',volume=.14){const ctx=getAudio(),o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(volume,start+.025);g.gain.exponentialRampToValueAtTime(.001,start+duration);o.connect(g);g.connect(ctx.destination);o.start(start);o.stop(start+duration+.02);audioNodes.push(o)}
function melody(slow=false,training=false){stopSound();const ctx=getAudio();const notes=training?[329.63,392,329.63,392,440,392]:state.song==='两只老虎'?[261.63,293.66,329.63,261.63,261.63,293.66,329.63,261.63]:state.song==='小雨沙沙'?[329.63,329.63,293.66,261.63,293.66,293.66,261.63]:[329.63,329.63,392,440,523.25,440,392,392,440,392];const step=slow?.8:.48;notes.forEach((f,i)=>tone(f,ctx.currentTime+.1+i*step,step*.9,'triangle'));$('.lesson-stage')?.classList.add('playing');playTimer=setTimeout(stopSound,(notes.length*step+.3)*1000);toast(training?'阶梯音练习：先听 Mi—Sol，再轻声模唱。':'正在播放电子音旋律示范')}
function metronome(){stopSound();const ctx=getAudio();for(let i=0;i<16;i++)tone(i%2?650:950,ctx.currentTime+i*.65,.08,'sine',.13);toast('节拍练习：第一拍拍手，第二拍轻拍膝盖。')}
function sound(type){stopSound();const ctx=getAudio();if(type==='birds'){for(let i=0;i<12;i++){const t=ctx.currentTime+i*.35;tone(1200+(i%3)*350,t,.14,'sine',.05)}}else{const buffer=ctx.createBuffer(1,ctx.sampleRate*5,ctx.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.15;const s=ctx.createBufferSource();s.buffer=buffer;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=type==='rain'?1700:400;const gain=ctx.createGain();gain.gain.setValueAtTime(0,ctx.currentTime);gain.gain.linearRampToValueAtTime(.7,ctx.currentTime+.5);gain.gain.linearRampToValueAtTime(0,ctx.currentTime+5);s.connect(filter);filter.connect(gain);gain.connect(ctx.destination);s.start();audioNodes.push(s)}toast('正在播放合成教学音效（约5秒）')}
async function startRecording(){try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前浏览器不支持录音，请使用示例演唱。');return}stream=await navigator.mediaDevices.getUserMedia({audio:true});if(state.route!=='listen'){stream.getTracks().forEach(t=>t.stop());return}const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{if(recordedURL)URL.revokeObjectURL(recordedURL);recordedURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));stream.getTracks().forEach(t=>t.stop());if(state.route==='listen')render()};recording=true;seconds=0;recorder.start();render();timer=setInterval(()=>{seconds++;if($('#record-time'))$('#record-time').textContent=`00:${String(seconds).padStart(2,'0')}`;if(seconds>=60)stopRecording()},1000)}catch(e){toast(e.name==='NotAllowedError'?'麦克风未获授权，可使用示例演唱继续体验。':'录音暂不可用，请检查麦克风或使用示例演唱。')}}
function stopRecording(){clearInterval(timer);recording=false;if(recorder?.state==='recording')recorder.stop()}
function sample(retest=false){if(recording)stopRecording();state.attempt=retest?2:1;state.analysis=retest?{pitch:86,rhythm:89,issue:'上行音更稳定，节拍也更均匀了。',strategy:'回到原句，巩固完整乐句',reason:'两项示例匹配均超过85%，由短音练习过渡到完整乐句。'}:{pitch:64,rhythm:81,issue:'上行到高音时，示例演唱出现偏低。',strategy:'阶梯音模唱 · Mi—Sol',reason:'音准示例值低于70%，节奏已较稳定。先练两音上行，再回到完整乐句。'};persist();render()}
function finish(){if(!state.analysis){toast('先完成一次示例听唱，再生成包含练习结果的报告。');go('listen');return}const r={song:state.song,grade:state.grade,students:state.students,duration:state.duration,...state.analysis,attempt:state.attempt,date:new Date().toLocaleDateString('zh-CN')};state.records.unshift(r);state.records=state.records.slice(0,20);selectedReport=r;persist();go('report')}
function sampleReport(song){selectedReport={song,grade:song==='茉莉花'?'四年级':'三年级',students:song==='茉莉花'?28:23,duration:40,pitch:song==='茉莉花'?86:78,rhythm:song==='茉莉花'?89:82,attempt:2,date:song==='茉莉花'?'9月10日':'9月8日'};go('report')}
function download(){const r=selectedReport||state.records[0];if(!r)return;const text=`山音AI课｜《${r.song}》课堂报告\n\n${r.grade} · ${r.students}人 · ${r.duration}分钟\n日期：${r.date}\n\n演示数据声明：本报告为交互原型示例，不是真实学生测评。\n音准匹配：${r.pitch}%\n节奏匹配：${r.rhythm}%\n练习次数：${r.attempt}\n\n教学建议：用3分钟复习阶梯音，先练Mi—Sol，再回到主题乐句。\n`;const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`山音AI课-${r.song}-课堂报告.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('课堂报告已下载')}
function voice(){const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){toast('当前浏览器不支持语音输入，可以直接输入课堂需求。');return}if(voiceRecognition){voiceRecognition.stop();voiceRecognition=null;return}const r=new API();voiceRecognition=r;r.lang='zh-CN';r.interimResults=false;r.onresult=e=>{state.request=e.results[0][0].transcript.slice(0,200);if($('#request')){$('#request').value=state.request;$('.counter').textContent=state.request.length+'/200'}persist()};r.onerror=()=>toast('语音识别暂不可用，请直接输入课堂需求。');r.onend=()=>voiceRecognition=null;r.start();toast('请说出课堂需求，语音识别可能需要联网。')}
function speak(){if(!window.speechSynthesis){toast('当前浏览器不支持语音朗读。');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(state.plan?.[state.stage]?.desc||'同学们，先听一听，再轻轻唱出来。');u.lang='zh-CN';u.rate=.85;speechSynthesis.speak(u)}
document.addEventListener('input',e=>{if(e.target.id==='request'){state.request=e.target.value;$('.counter').textContent=state.request.length+'/200'}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.route){go(b.dataset.route);return}if(b.dataset.tab){state.tab=b.dataset.tab;render();return}if(b.dataset.report!==undefined){selectedReport=state.records[+b.dataset.report];go('report');return}if(b.dataset.class!==undefined){const classes=state.classes||[{name:'四年级',students:28,level:'初学者'},{name:'三年级',students:23,level:'初学者'},{name:'五年级',students:26,level:'有一定基础'}];const c=classes[+b.dataset.class];state.grade=c.name;state.students=c.students;state.level=c.level;state.request=`帮${c.name}${c.students}个孩子准备一节${state.duration}分钟的《${state.song}》音乐课，${c.level}，${state.equipment}。`;persist();go('home');return}if(b.dataset.soundlesson){state.request=`帮${state.grade}${state.students}个孩子准备一节${state.duration}分钟的《${state.song}》音乐课，从${b.dataset.soundlesson}的模仿活动开始。`;persist();go('home');return}const a=b.dataset.action;switch(a){case'home':case'listen':case'reports':case'sounds':go(a);break;case'prepare':prepare();break;case'conditions':conditions();break;case'close-modal':closeModal();break;case'continue':if(!state.plan)makePlan();state.tab='teach';go('classroom');break;case'timeline':state.tab='timeline';render();break;case'start-class':state.tab='teach';render();break;case'next-stage':state.stage=Math.min(6,state.stage+1);stopSound();persist();render();break;case'prev-stage':state.stage=Math.max(0,state.stage-1);stopSound();persist();render();break;case'melody':melody();break;case'slow-melody':melody(true);break;case'training':melody(true,true);break;case'metronome':metronome();break;case'speak':speak();break;case'voice':voice();break;case'record':startRecording();break;case'stop-record':stopRecording();break;case'sample':sample();break;case'retest':sample(state.attempt===1);break;case'reset-analysis':state.analysis=null;state.attempt=0;persist();render();break;case'finish':finish();break;case'sample-report':sampleReport(b.dataset.song||'茉莉花');break;case'download':download();break;case'next-lesson':state.request=`帮${state.grade}${state.students}个孩子准备一节${state.duration}分钟的《${state.song}》音乐课，先用3分钟复习阶梯音，再练主题乐句。`;go('home');break;case'notifications':toast('欢迎来到山音教室，今天也让音乐在山里发生。');break;case'birds':case'rain':case'wind':sound(a);break;case'add-class':modal('<h2>添加一个新班级</h2><form id="class-form"><div class="field"><label for="class-name">班级名称</label><input id="class-name" name="name" maxlength="16" placeholder="例如：四年级二班" required></div><div class="condition-grid" style="margin-top:16px"><div class="field"><label for="class-count">人数</label><input id="class-count" name="students" type="number" min="1" max="80" value="28" required></div><div class="field"><label for="class-level">音乐基础</label><select id="class-level" name="level"><option>初学者</option><option>有一定基础</option></select></div></div><div class="panel-actions"><button class="btn" type="submit">保存班级</button></div></form>');break}});
document.addEventListener('submit',e=>{if(e.target.id==='condition-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));Object.assign(state,d,{students:+d.students,duration:+d.duration});state.request=`帮${state.grade}${state.students}个孩子准备一节${state.duration}分钟的《${state.song}》音乐课，${state.level}，${state.equipment}。`;if(state.plan)makePlan();persist();closeModal();render();toast('课堂条件已保存')}if(e.target.id==='class-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.name.trim())return;state.classes??=[{name:'四年级',students:28,level:'初学者',emoji:'🌻'},{name:'三年级',students:23,level:'初学者',emoji:'🌱'},{name:'五年级',students:26,level:'有一定基础',emoji:'🌳'}];state.classes.push({...d,name:d.name.trim(),students:+d.students,emoji:'🌼'});persist();closeModal();render();toast('新班级已保存')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});window.addEventListener('beforeunload',()=>{stream?.getTracks().forEach(t=>t.stop());persist()});render();
